<#
  Fix-RemoveNegotiateAndLiveJobs.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  PART 1 - NEGOTIATE BUTTON REMOVED
  The vendor sets the price for a job, and that price isn't up for a
  counter-offer - so the "Suggest a different price" button and its input
  field are gone from src\components\rider\IncomingOrderCard.jsx. A rider
  now only ever sees Accept Signal (or decline). The underlying bid
  columns/RPC/dashboard handler are left in place untouched (unreachable,
  not deleted) in case a pending bid already exists from before this
  change - it still displays gracefully as a "waiting for vendor" state
  rather than erroring out.

  PART 2 - JOBS NOT APPEARING LIVE (needed a refresh)
  Root cause found and already fixed directly in Supabase (no code change,
  nothing to run here for this part - already live): the
  order_broadcasts table was never added to the supabase_realtime
  publication. The rider dashboard's subscription code was correct the
  whole time - Postgres just never emitted change events for that table
  in the first place, so a brand new job broadcast never reached a
  rider's screen until they manually refreshed and re-fetched. Same class
  of bug as the earlier orders/riders/messages realtime fix - the table
  itself was the missing piece.

  Writes full file content (base64-encoded, written as raw bytes - no
  PowerShell string-escaping of JS/JSX, no BOM-injection risk). Backs up
  the existing file to .fix-backup-negotiate-and-live\ first.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-RemoveNegotiateAndLiveJobs.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-negotiate-and-live"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

if (-not (Test-Path -LiteralPath (Join-Path $root "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FileFromBase64($relPath, $b64) {
    $full = Get-FullPath $relPath
    $targetParent = Split-Path $full -Parent
    if (-not (Test-Path -LiteralPath $targetParent)) { New-Item -ItemType Directory -Path $targetParent -Force | Out-Null }
    Backup-Path $full
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
}

Write-Host "`nApplying negotiate-button removal:" -ForegroundColor Cyan

$b64_CARD = ""
Write-FileFromBase64 "src\components\rider\IncomingOrderCard.jsx" $b64_CARD

Write-Host "`nDone. Backup saved under .fix-backup-negotiate-and-live\" -ForegroundColor Cyan
Write-Host "The live-jobs fix needed no code change - already applied directly in Supabase." -ForegroundColor Cyan
Write-Host "Next: npm run build (or your usual dev command), then redeploy to Vercel." -ForegroundColor Cyan
